                DCB "fdt move   <fdt> <newaddr> <length> - Copy the fdt to <addr> and"
                DCB " make it active",0xA
                DCB "fdt resize [<extrasize>]            - Resize fdt to size + paddi"
                DCB "ng to 4k addr + some optional <extrasize> if needed",0xA
                DCB "fdt print  <path> [<prop>]          - Recursive print starting a"
                DCB "t <path>",0xA
                DCB "fdt list   <path> [<prop>]          - Print one level starting a"
                DCB "t <path>",0xA
                DCB "fdt get value <var> <path> <prop>   - Get <property> and store i"
                DCB "n <var>",0xA
                DCB "fdt get name <var> <path> <index>   - Get name of node <index> a"
                DCB "nd store in <var>",0xA
                DCB "fdt get addr <var> <path> <prop>    - Get start address of <prop"
                DCB "erty> and store in <var>",0xA
                DCB "fdt get size <var> <path> [<prop>]  - Get size of [<property>] o"
                DCB "r num nodes and store in <var>",0xA
                DCB "fdt set    <path> <prop> [<val>]    - Set <property> [to <val>]",0xA
                DCB "fdt mknode <path> <node>            - Create a new node after <p"
                DCB "ath>",0xA
                DCB "fdt rm     <path> [<prop>]          - Delete the node or <proper"
                DCB "ty>",0xA
                DCB "fdt header                          - Display header info",0xA
                DCB "fdt bootcpu <id>                    - Set boot cpuid",0xA
                DCB "fdt memory <addr> <size>            - Add/Update memory node",0xA
                DCB "fdt rsvmem print                    - Show current mem reserves",0xA
                DCB "fdt rsvmem add <addr> <size>        - Add a mem reserve",0xA
                DCB "fdt rsvmem delete <index>           - Delete a mem reserves",0xA
                DCB "fdt chosen [<start> <end>]          - Add/update the /chosen bra"
                DCB "nch in the tree",0xA
                DCB "                                        <start>/<end> - initrd s"
                DCB "tart/end addr",0xA
                DCB "NOTE: Dereference aliases by omitting the leading '/', e.g. fdt "
                DCB "print ethernet0.",0
                DCW 0, 0, 0
                DCQ 1
                DCQ qword_30+0x10
